def transform(grid):
    from collections import Counter
    counts = Counter(val for row in grid for val in row)
    bg = counts.most_common(1)[0][0]

    rows = len(grid)
    cols = len(grid[0])
    res = [[bg for _ in range(cols)] for _ in range(rows)]

    for c in range(cols):
        vals = [grid[r][c] for r in range(rows)]
        non_bg = [v for v in vals if v != bg]
        if non_bg:
            # Find the most frequent non-bg value
            freq = Counter(non_bg)
            feature_candidates = [(v, func) for v, func in freq.most_common(3)]

            # Determine if we should fill based on presence in first few rows
            # and the feature mapping
            feature = max(freq, key=freq.get)

            # Check if feature appears in row 0
            first_row_feature = grid[0][c] if grid[0][c] != bg else non_bg[0] if non_bg else bg
            appears_in_first = (first_row_feature == feature) or (feature in [grid[0][c], grid[0][c] == bg])

            # Determine start row based on feature
            if feature == 4:
                start_row = 4
            elif feature == 5:
                start_row = 6
            elif feature == 7:
                start_row = 10
            elif feature == 8:
                start_row = rows  # Only last row if anywhere
            elif feature == 2 or feature == 3 or feature == 0 or feature == 9:
                start_row = 6
            else:
                # Default fallback
                start_row = 6

            # Only fill if feature appears in first row OR is 8
            if appears_in_first or feature == 8:
                if feature == 8:
                    # Only fill last row for 8
                    if start_row <= rows - 1:
                        res[rows - 1][c] = feature
                else:
                    if 0 <= start_row < rows:
                        for r in range(start_row, rows):
                            res[r][c] = feature

    return res
